import{_ as d,C as n,o as c,c as i,a2 as l,E as t,w as a,a as s}from"./chunks/framework.CeYlivdO.js";const y=JSON.parse('{"title":"Futures, Tasks, and Thread Pools","description":"From `std::async` to `promise`/`packaged_task`, building flexible asynchronous task channels and thread pool infrastructure","frontmatter":{"title":"Futures, Tasks, and Thread Pools","description":"From `std::async` to `promise`/`packaged_task`, building flexible asynchronous task channels and thread pool infrastructure","translation":{"source":"documents/vol5-concurrency/ch05-future-task-threadpool/index.md","source_hash":"9ab6af6303383bc38e7c506c7c5890021e60b1d1b148e42b988310632eb30b75","translated_at":"2026-05-20T04:43:25.143676+00:00","engine":"anthropic","token_count":220}},"headers":[],"relativePath":"en/vol5-concurrency/ch05-future-task-threadpool/index.md","filePath":"en/vol5-concurrency/ch05-future-task-threadpool/index.md","lastUpdated":null}'),u={name:"en/vol5-concurrency/ch05-future-task-threadpool/index.md"};function h(p,e,f,m,k,_){const o=n("ChapterLink"),r=n("ChapterNav");return c(),i("div",null,[e[4]||(e[4]=l('<h1 id="futures-tasks-and-thread-pools" tabindex="-1">Futures, Tasks, and Thread Pools <a class="header-anchor" href="#futures-tasks-and-thread-pools" aria-label="Permalink to &quot;Futures, Tasks, and Thread Pools&quot;">​</a></h1><p>In previous chapters, we worked extensively with low-level primitives: <code>thread</code>, <code>mutex</code>, <code>atomic</code>, and <code>condition variable</code>. These give us precise control, but they also impose a significant manual management burden—we have to design synchronization mechanisms ourselves, pass results manually, and handle errors on our own. The C++ standard library provides a set of higher-level asynchronous abstractions to simplify this work: <code>future</code> is a result container, <code>promise</code> is the writing end for a value, <code>packaged_task</code> is a task wrapper, and <code>async</code> is the most convenient way to launch a task. Together, they form the infrastructure for thread pools and task queues.</p><p>In this chapter, we start with <code>std::async</code> and <code>std::future</code> to understand the launch strategies for asynchronous tasks and the mechanisms for retrieving results. We then dive into <code>std::promise</code> and <code>std::packaged_task</code> to learn how to manually control value setting and task execution. Finally, we discuss <code>std::shared_future</code> and thread pool design patterns, tying together all the components we have learned so far.</p><h2 id="chapter-contents" tabindex="-1">Chapter Contents <a class="header-anchor" href="#chapter-contents" aria-label="Permalink to &quot;Chapter Contents&quot;">​</a></h2>',4)),t(r,{variant:"sub"},{default:a(()=>[t(o,{href:"01-std-async-and-future"},{default:a(()=>[...e[0]||(e[0]=[s("std::async 与 future",-1)])]),_:1}),t(o,{href:"02-promise-and-packaged-task"},{default:a(()=>[...e[1]||(e[1]=[s("promise 与 packaged_task",-1)])]),_:1}),t(o,{href:"03-jthread-and-stop-token"},{default:a(()=>[...e[2]||(e[2]=[s("jthread 与停止令牌",-1)])]),_:1}),t(o,{href:"04-thread-pool"},{default:a(()=>[...e[3]||(e[3]=[s("线程池设计",-1)])]),_:1})]),_:1})])}const g=d(u,[["render",h]]);export{y as __pageData,g as default};
